            file_size = int(content_length)
            if file_size <= 0:
                raise ValueError("Invalid file size reported by server.")

            num_parts = math.ceil(file_size / max_part_size)
            if num_parts > MAX_PARTS_LIMIT:
                adjusted_part_size = math.ceil(file_size / MAX_PARTS_LIMIT)
                num_parts = MAX_PARTS_LIMIT
                actual_part_size = adjusted_part_size
            else:
