import subprocess
import shlex
import os


PREDEFINED_FASTA = "/data/reference/extra_sequences.fasta"
PREDEFINED_GTF = "/data/reference/extra_annotations.gtf"


def append_predefined_files(gtf_file: str, fasta_file: str) -> None:
    for path in (gtf_file, fasta_file, PREDEFINED_GTF, PREDEFINED_FASTA):
        if not isinstance(path, str) or not path:
            raise ValueError(f"Invalid file path: {path!r}")
        normalized = os.path.normpath(path)
        if normalized != path.rstrip("/"):
            raise ValueError(f"Path traversal detected in: {path!r}")

    for path in (gtf_file, fasta_file):
        if not os.path.isfile(path):
            raise FileNotFoundError(f"Target file not found: {path!r}")

    for path in (PREDEFINED_GTF, PREDEFINED_FASTA):
        if not os.path.isfile(path):
            raise FileNotFoundError(f"Predefined file not found: {path!r}")

    pairs = [
        (PREDEFINED_GTF, gtf_file),
        (PREDEFINED_FASTA, fasta_file),
    ]

    for src, dst in pairs:
        with open(src, "rb") as source, open(dst, "ab") as destination:
            while chunk := source.read(65536):
                destination.write(chunk)
