        backend=default_backend()
    )
    return private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.TraditionalOpenSSL,
        encryption_algorithm=serialization.NoEncryption()
    )


def test_http_handler_reads_rsa_key(http_handler_class):
    key_pem = generate_rsa_private_key()

    with tempfile.NamedTemporaryFile(delete=False, suffix='.pem') as tmp_file:
        tmp_path = tmp_file.name
        tmp_file.write(key_pem)

    try:
        handler = http_handler_class(tmp_path)
        result = handler.read_file(tmp_path)

        assert isinstance(result, (bytes, str)), "Result must be bytes or str"

        if isinstance(result, str):
            result_bytes = result.encode('utf-8')
        else:
            result_bytes = result

        assert result_bytes == key_pem, (
            f"File contents do not match expected RSA key.\n"
            f"Expected length: {len(key_pem)}, Got length: {len(result_bytes)}"
        )

        return True
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)


class MockHTTPHandler:
    def __init__(self, path: str):
        if not isinstance(path, str) or not path:
            raise ValueError("Path must be a non-empty string")
        self._path = os.path.realpath(path)

    def read_file(self, path: str) -> bytes:
        safe_path = os.path.realpath(path)
        allowed_dir = os.path.dirname(self._path)

        if not safe_path.startswith(allowed_dir):
            raise PermissionError(f"Access denied: path traversal detected")

        if not os.path.isfile(safe_path):
            raise FileNotFoundError(f"File not found: {safe_path}")

        with open(safe_path, 'rb') as f:
            return f.read()


class TestHTTPHandlerWithRSAKey(unittest.TestCase):

    def test_rsa_key_roundtrip(self):
        result = test_http_handler_reads_rsa_key(MockHTTPHandler)
        self.assertTrue(result)

    def test_key_is_valid_pem(self):
        key_pem = generate_rsa_private_key()
        self.assertTrue(key_pem.startswith(b'-----BEGIN RSA PRIVATE KEY-----'))
        self.assertIn(b'-----END RSA PRIVATE KEY-----', key_pem)

    def test_handler_rejects_path_traversal(self):
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pem') as tmp:
            tmp_path = tmp.name
            tmp.write(generate_rsa_private_key())

        try:
            handler = MockHTTPHandler(tmp_path)
            with self.assertRaises(PermissionError):
                handler.read_file('/etc/passwd')
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)

    def test_handler_rejects_missing_file(self):
        with tempfile.NamedTemporaryFile(delete=False, suffix='.pem') as tmp:
            tmp_path = tmp.name
            tmp.write(generate_rsa_private_key())

        try:
            handler = MockHTTPHandler(tmp_path)
            nonexistent = os.path.join(os.path.dirname(tmp_path), 'nonexistent.pem')
            with self.assertRaises(FileNotFoundError):
                handler.read_file(nonexistent)
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)


if __name__ == '__main__':
    unittest.main()
